const sharp = require('sharp');
const b64 = input.imageB64;
if (!b64 || typeof b64 !== 'string') throw new Error('imageB64 input missing or not a string');
const maxEdge = Number(input.maxEdge) > 0 ? Number(input.maxEdge) : 1600;
const buf = Buffer.from(b64, 'base64');

let img = sharp(buf, { failOn: 'none' })
  .rotate()        // honor EXIF orientation from phone cameras
  .grayscale()     // it's a B&W document — drop chroma noise
  .normalize();    // stretch tonal range so faint ink reaches full black/white

// Gentle extra contrast + unsharp mask to crisp up faded thermal receipts.
// a>1 steepens contrast; b shifts the black point down slightly.
img = img.linear(1.15, -15).sharpen();

// Downscale the long edge to maxEdge; never upscale (withoutEnlargement).
// Smaller images = fewer vision tokens = lower VRAM and faster inference.
img = img.resize({ width: maxEdge, height: maxEdge, fit: 'inside', withoutEnlargement: true });

const out = await img.jpeg({ quality: 90 }).toBuffer();
const meta = await sharp(out).metadata();
fs.writeFileSync(path.join(outputDir, 'receipt-pre.jpg'), out);
return { width: meta.width, height: meta.height, bytes: out.length };
